\title{The Exact Constrained-Coset Guesswork Exponent \\ at the Symmetric Source}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study the exponential growth rate of the $\rho$-th moment of \emph{constrained
coset guesswork}: the number of trials an optimal adversary needs to identify a
secret noise vector when the search is restricted to a single coset of a rate-$R$
binary linear code. For an i.i.d.\ Bernoulli($p$) source the unconstrained
guesswork moment grows with the Arıkan--Merhav exponent
$E(\rho,p) = (1+\rho)\log_2\big(p^{1/(1+\rho)} + (1-p)^{1/(1+\rho)}\big)$. We prove,
at the maximal-entropy source $p = \tfrac12$, that constraining to a rate-$R$
coset lowers the exponent by \emph{exactly} $\rho(1-R)$, yielding the closed form
$\Ecoset(\rho,R,\tfrac12) = \rho R$. In contrast to prior abstract treatments that
\emph{postulate} a moment sequence with the correct unconstrained rate, we
\emph{construct} the guesswork moment from first principles as the exact average
$M(N) = N^{-1}\sum_{k=1}^{N} k^{\rho}$ over $N$ equiprobable candidates and
\emph{derive} the rate. The engine of the proof is an elementary two-sided
estimate $2^{(j-1)(\rho+1)} \le \sum_{k=1}^{2^{j}} k^{\rho} \le 2^{\,j(\rho+1)}$,
whose logarithmic form, combined with a squeeze argument, pins the constrained
rate at $\rho R$ whenever the coset dimension satisfies $k_m/m \to R$. We also
establish $E(\rho,\tfrac12) = \rho$ and thereby express the result as the exact
shift $\rho R = E(\rho,\tfrac12) - \rho(1-R)$, recovering the unconstrained rate
$\rho$ as the special case $R = 1$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The guessing game}
Consider an adversary who must identify an unknown secret $X$ drawn from a finite
set by submitting guesses one at a time, receiving after each a single bit of
feedback. Fixing a deterministic ordering of the candidate set, the
\emph{guessing rank} $G(x)$ of the true value $x$ is its position in that
ordering. An optimal adversary orders candidates by non-increasing probability.

Rather than the mean number of guesses, which is blind to tail risk, one studies
the $\rho$-th \emph{moment}
\[
\E\!\left[G(X)^\rho\right] = \sum_x P(x)\, G(x)^\rho, \qquad \rho > 0,
\]
where $\rho$ interpolates between average-case ($\rho \to 0$) and worst-case
($\rho \to \infty$) sensitivity.

\subsection{The Arıkan--Merhav exponent}
Let the secret be an $n$-bit vector with i.i.d.\ Bernoulli($p$) coordinates. The
$\rho$-th guesswork moment grows as $2^{n E(\rho,p) + o(n)}$, where
\[
E(\rho, p) = (1+\rho)\,\log_2\!\left( p^{\frac{1}{1+\rho}} + (1-p)^{\frac{1}{1+\rho}} \right).
\]
The bracketed term is an exponentiated Rényi entropy of order
$\alpha = \frac{1}{1+\rho}$.

\subsection{Constrained coset guesswork}
A binary linear code $\mathcal{C} \subseteq \F_2^n$ of rate $R$ partitions
$\F_2^n$ into $2^{(1-R)n}$ cosets, each of size $2^{Rn}$. When the adversary knows
the coset (the syndrome) of the secret noise vector, the candidate set shrinks
from $2^n$ to $2^{Rn}$. We call the resulting $\rho$-th moment the
\emph{constrained coset guesswork moment}, with exponent $\Ecoset(\rho, R, p)$.

\subsection{Contribution}
Prior work established abstractly that coset density compression lowers the
exponent by $\rho(1-R)$, but \emph{postulated} an unconstrained moment sequence
with the Arıkan--Merhav rate. We remove that hypothesis at $p = \tfrac12$: we
construct the moment, prove the power-sum sandwich, derive the rate $\rho R$ by a
squeeze argument, identify $E(\rho,\tfrac12) = \rho$, and read off the exact shift
$\rho R = E(\rho,\tfrac12) - \rho(1-R)$.

\section{Preliminaries}

Throughout, $\rho > 0$ and $\log_2$ is the base-2 logarithm. For $b > 0$ and real
$t$ we use $b^t := \exp(t\ln b)$, so $(2^a)^b = 2^{ab}$ and $\log_2(2^t) = t$.

\begin{definition}[Arıkan--Merhav exponent]
For $\rho > 0$ and $p \in (0,1)$,
\[
E(\rho, p) := (1+\rho)\,\log_2\!\left( p^{\frac{1}{1+\rho}} + (1-p)^{\frac{1}{1+\rho}} \right).
\]
\end{definition}

\section{The guesswork moment for an equiprobable candidate set}

At $p = \tfrac12$ every length-$n$ vector has probability $2^{-n}$, so within any
candidate set of size $N$ all candidates are equiprobable and an optimal
adversary realizes the ranks $1, 2, \dots, N$ exactly. The $\rho$-th moment is
therefore the exact average of $k^\rho$.

\begin{definition}[Power sum]
For $\rho \in \Real$ and $N \in \Nat$,
\[
S(\rho, N) := \sum_{k=1}^{N} k^{\rho} = \sum_{k=0}^{N-1} (k+1)^{\rho}.
\]
\end{definition}

\begin{definition}[Guesswork moment]
For $N = 2^{k}$ equiprobable candidates,
\[
M(\rho, k) := 2^{-k}\, S(\rho, 2^{k}) = \frac{1}{2^{k}}\sum_{j=1}^{2^{k}} j^{\rho}.
\]
For coset guessing over a rate-$R$ code, $k = k_m$ with $k_m/m \to R$; we write
$M_{\mathrm{coset}}(\rho, k_m, m) := 2^{-k_m} S(\rho, 2^{k_m})$.
\end{definition}

\begin{proposition}[Positivity]
For every $\rho \in \Real$ and $N \ge 1$, $S(\rho, N) > 0$.
\end{proposition}
\begin{proof}
Each summand $(k+1)^\rho > 0$ and the range is nonempty.
\end{proof}

\section{The power-sum sandwich}

\begin{theorem}[Upper bound]
For $\rho \ge 0$ and $j \in \Nat$, $\ S(\rho, 2^{j}) \le 2^{\,j(\rho+1)}$.
\end{theorem}
\begin{proof}
Each term $(i+1)^\rho$ with $0 \le i < 2^j$ satisfies $i+1 \le 2^j$, so by
monotonicity of $x \mapsto x^\rho$ ($\rho \ge 0$), $(i+1)^\rho \le 2^{j\rho}$.
Summing $2^j$ terms gives $S \le 2^j \cdot 2^{j\rho} = 2^{j(\rho+1)}$.
\end{proof}

\begin{theorem}[Lower bound]
For $\rho \ge 0$ and $j \ge 1$, $\ 2^{\,(j-1)(\rho+1)} \le S(\rho, 2^{j})$.
\end{theorem}
\begin{proof}
Restrict to indices $k \in [2^{j-1}, 2^j)$, a block of $2^{j-1}$ nonnegative
terms. For each, $k+1 > 2^{j-1}$, so $(k+1)^\rho \ge 2^{(j-1)\rho}$. Hence
$S(\rho, 2^j) \ge 2^{j-1}\cdot 2^{(j-1)\rho} = 2^{(j-1)(\rho+1)}$.
\end{proof}

\begin{theorem}[Logarithmic sandwich]\label{thm:sandwich}
For $\rho \ge 0$ and $j \ge 1$,
\[
(j-1)(\rho+1) \le \log_2 S(\rho, 2^{j}) \le j(\rho+1).
\]
\end{theorem}
\begin{proof}
Apply the increasing map $\log_2$ (valid since $S > 0$) to the two preceding
bounds and use $\log_2(2^t) = t$.
\end{proof}

The upper and lower bounds differ by the constant $\rho + 1$, independent of $j$;
normalization annihilates this gap.

\section{Main theorem: exact constrained-coset rate}

\begin{theorem}[Exact constrained-coset exponent at $p = \tfrac12$]\label{thm:main}
Let $\rho > 0$ and $R \in \Real$. Let $(k_m)_{m \ge 1}$ satisfy $k_m \to \infty$
and $k_m/m \to R$. Then
\[
\frac{1}{m}\,\log_2 M_{\mathrm{coset}}(\rho, k_m, m)
= \frac{1}{m}\,\log_2\!\left( 2^{-k_m}\sum_{j=1}^{2^{k_m}} j^{\rho} \right)
\xrightarrow[m\to\infty]{} \rho R.
\]
\end{theorem}
\begin{proof}
For $m$ with $k_m \ge 1$, write $\log_2(2^{-k_m} S) = -k_m + \log_2 S$ with
$S = S(\rho, 2^{k_m})$. By Theorem~\ref{thm:sandwich} with $j = k_m$,
\[
-k_m + (k_m-1)(\rho+1) \le \log_2 M_{\mathrm{coset}} \le -k_m + k_m(\rho+1),
\]
i.e.\ $k_m\rho - (\rho+1) \le \log_2 M_{\mathrm{coset}} \le k_m\rho$. Dividing by
$m > 0$,
\[
\frac{k_m}{m}\rho - \frac{\rho+1}{m}
\le \frac{1}{m}\log_2 M_{\mathrm{coset}}
\le \frac{k_m}{m}\rho.
\]
As $m \to \infty$ both bounds tend to $R\rho$ (using $k_m/m \to R$ and
$\frac{\rho+1}{m} \to 0$); the squeeze theorem gives the claim.
\end{proof}

\section{The exponent shift}

\begin{theorem}[Symmetric-source exponent]\label{thm:half}
For $\rho > 0$, $\ E(\rho, \tfrac12) = \rho$.
\end{theorem}
\begin{proof}
With $s := \tfrac{1}{1+\rho}$, $\ (\tfrac12)^s + (\tfrac12)^s = 2\cdot 2^{-s} = 2^{1-s}$,
so $\log_2(2^{1-s}) = 1 - s = \tfrac{\rho}{1+\rho}$, and
$E(\rho,\tfrac12) = (1+\rho)\cdot\tfrac{\rho}{1+\rho} = \rho$.
\end{proof}

\begin{corollary}[Unconstrained rate]
With $R = 1$ (i.e.\ $k_m = m$), $\ \frac{1}{m}\log_2 M(\rho, m) \to \rho = E(\rho,\tfrac12)$.
\end{corollary}

\begin{theorem}[Exact exponent shift]\label{thm:shift}
For $\rho > 0$ and $R \in [0,1]$,
\[
\Ecoset(\rho, R, \tfrac12) = \rho R = E(\rho, \tfrac12) - \rho(1 - R).
\]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:main} gives $\rho R$; Theorem~\ref{thm:half} gives
$E(\rho,\tfrac12) = \rho$, and $\rho - \rho(1-R) = \rho R$.
\end{proof}

The shift is purely structural: it depends only on the code rate $R$ and the risk
parameter $\rho$, not on the source. Setting $p = \tfrac12$ isolates the
coset-compression mechanism.

\section{Applications and discussion}

The exponent $\rho R$ quantifies the tail-aware cost of within-coset exhaustive
search for a syndrome-decoding adversary, and the shift $\rho(1-R)$ measures how
much structural redundancy erodes guessing hardness in code-based cryptography.
Any general-$p$ formula must reduce to $\rho R$ at $p = \tfrac12$, so
Theorem~\ref{thm:shift} is a rigorous benchmark.

\paragraph{Future work.}
(i) General $p \ne \tfrac12$ via tilted, weight-grouped enumeration to reach
$E(\rho,p)$; (ii) averaging over random $[n, Rn]$ codes with the density factor
$2^{-(1-R)n}$ via a first-moment method; (iii) concentration and a matching
converse; (iv) $q$-ary alphabets giving
$\rho\,H^{(q)}_{1/(1+\rho)}(p) - \rho(1-R)$; (v) Euler--Maclaurin refinement of
the $O((\rho+1)/m)$ convergence.

\section{Conclusion}

Constrained coset guesswork at the symmetric source has exponential growth rate
exactly $\rho R$, an exact downward shift of $\rho(1-R)$ from the unconstrained
exponent $\rho$. The proof rests on the elementary bracketing of
$\sum_{k=1}^{2^j} k^\rho$ between $2^{(j-1)(\rho+1)}$ and $2^{j(\rho+1)}$, whose
constant gap vanishes under normalization.

