"""Coset-guesswork rate convergence to rho*R at the symmetric source."""
from __future__ import annotations
import math


def guesswork_moment(rho: float, k: int) -> float:
    """M(rho,k) = 2^{-k} sum_{j=1}^{2^k} j^rho."""
    return (2.0 ** (-k)) * sum(float(j) ** rho for j in range(1, 2 ** k + 1))


def coset_rate(rho: float, R: float, m: int) -> float:
    """Finite-m estimate (1/m) log2 M(rho, floor(R m)) of the coset exponent."""
    k_m = max(1, int(math.floor(R * m)))
    return (1.0 / m) * math.log2(guesswork_moment(rho, k_m))


if __name__ == "__main__":
    rho, R = 1.0, 0.6
    for m in (4, 8, 12, 16, 20):
        print(f"m={m:2d}  rate={coset_rate(rho, R, m):.5f}  target(rho*R)={rho*R:.3f}")

"""Numerically confirm the exact exponent shift rho - rho*R = rho*(1-R)."""
from __future__ import annotations
import math


def am_exponent(rho: float, p: float) -> float:
    """Arikan-Merhav exponent; equals rho at p=1/2."""
    s = 1.0 / (1.0 + rho)
    return (1.0 + rho) * math.log2(p ** s + (1.0 - p) ** s)


def guesswork_moment(rho: float, k: int) -> float:
    return (2.0 ** (-k)) * sum(float(j) ** rho for j in range(1, 2 ** k + 1))


if __name__ == "__main__":
    rho, m = 2.0, 20
    unconstrained = (1.0 / m) * math.log2(guesswork_moment(rho, m))
    print(f"E(rho,1/2) = {am_exponent(rho, 0.5):.6f}  (should equal rho={rho})")
    for R in (0.25, 0.5, 0.75, 1.0):
        k_m = max(1, int(math.floor(R * m)))
        rate = (1.0 / m) * math.log2(guesswork_moment(rho, k_m))
        print(f"R={R:.2f}  shift(rho(1-R))={rho*(1-R):.3f}  "
              f"empirical(rho-rate)={unconstrained - rate:.3f}")

