function GuessworkMoment(rho, k):
    N <- 2^k
    running <- 0
    for j in 1..N:
        running <- running + j^rho
    return 2^{-k} * running

function VerifySandwich(rho, j):
    lower <- 2^{(j-1)(rho+1)}
    upper <- 2^{j(rho+1)}
    S <- sum_{k=1}^{2^j} k^rho
    return (lower <= S) and (S <= upper)

function CosetExponentEstimate(rho, R, m):
    k_m <- floor(R * m)
    M <- 2^{-k_m} * sum_{j=1}^{2^{k_m}} j^rho
    return (1/m) * log2(M)
